export const UpdateActivityResponse = zod.object({
  "id": zod.string(),
  "classId": zod.string(),
  "eyebrow": zod.string().nullish(),
  "title": zod.string(),
  "task": zod.string(),
  "prompts": zod.array(zod.string()),
  "contentFormatting": zod.union([zod.object({
  "version": zod.literal(1),
  "task": zod.array(zod.object({
  "text": zod.string().min(1).max(updateActivityResponseContentFormattingOneTaskItemTextMax),
  "bold": zod.boolean().optional(),
  "underline": zod.boolean().optional(),
  "highlight": zod.boolean().optional()
})).max(updateActivityResponseContentFormattingOneTaskMax).optional(),
  "prompts": zod.array(zod.array(zod.object({
  "text": zod.string().min(1).max(updateActivityResponseContentFormattingOnePromptsItemItemTextMax),
  "bold": zod.boolean().optional(),
  "underline": zod.boolean().optional(),
  "highlight": zod.boolean().optional()
})).max(updateActivityResponseContentFormattingOnePromptsItemMax)).max(updateActivityResponseContentFormattingOnePromptsMax).optional()
}),zod.null()]).optional(),
  "durationMinutes": zod.number().min(1).multipleOf(updateActivityResponseDurationMinutesMultipleOf),
  "deviceMode": zod.enum(['off', 'on']),
  "technologyMode": zod.enum(['no_computer', 'computer_available', 'computer_required']).optional().describe('Three-state creation setting; legacy deviceMode remains available for saved compatibility.'),
  "arrivalInstructions": zod.string().nullish(),
  "resourceUrl": zod.string().nullish(),
  "resourceNote": zod.string().nullish(),
  "visualUrl": zod.string().nullish(),
  "visualDescription": zod.string().nullish(),
  "visuals": zod.array(zod.object({
  "url": zod.string().min(1),
  "description": zod.string().nullish()
})).max(updateActivityResponseVisualsMax).optional(),
  "materials": zod.array(zod.string()).optional(),
  "teacherNote": zod.string().nullish(),
  "sourceTopic": zod.string().nullish(),
  "sourceGoal": zod.string().nullish(),
  "sourceUnitId": zod.string().nullish(),
  "sourceUnitName": zod.string().nullish(),
  "sourceChipIds": zod.array(zod.string()).optional(),
  "sourceActivityId": zod.string().nullish(),
  "savedContextSnapshot": zod.array(zod.object({
  "contextId": zod.string().nullish(),
  "label": zod.string().min(1).max(updateActivityResponseSavedContextSnapshotItemLabelMax),
  "category": zod.string().max(updateActivityResponseSavedContextSnapshotItemCategoryMax).nullish(),
  "details": zod.string().max(updateActivityResponseSavedContextSnapshotItemDetailsMax).nullish()
})).optional(),
  "style": zod.string().nullish(),
  "presentationTheme": zod.union([zod.object({
  "kind": zod.enum(['curated', 'custom']),
  "themeId": zod.string().optional(),
  "accentId": zod.string().optional(),
  "typographyId": zod.string().optional(),
  "sourceThemeId": zod.string().optional(),
  "anchors": zod.object({
  "background": zod.string().regex(updateActivityResponsePresentationThemeOneAnchorsBackgroundRegExp),
  "text": zod.string().regex(updateActivityResponsePresentationThemeOneAnchorsTextRegExp),
  "accent": zod.string().regex(updateActivityResponsePresentationThemeOneAnchorsAccentRegExp)
}).optional()
}),zod.null()]).optional(),
  "favorite": zod.boolean(),
  "duplicatedFrom": zod.string().nullish(),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})


